"""Maintain the initial manual revision. Text stays in native language resources."""
from pathlib import Path
import json
import re
from chinese_terms import localize

root = Path(__file__).resolve().parents[1]
base = root / 'src/main/resources/assets/sablelife'
locales = [json.loads((base / f'lang/{lang}.json').read_text(encoding='utf-8')) for lang in ('en_us', 'zh_cn')]
entries = []
tabs = ('usage', 'settings', 'example', 'troubleshooting')

def text(key, en, zh):
    for locale, value in zip(locales, (en, zh)):
        locale['manual.sablelife.' + key] = value
    return 'manual.sablelife.' + key

ui = {
 'title': ('Operating manual', '操作手册'), 'back': ('Back', '返回'),
 'search': ('Search name or ID', '搜索名称或ID'), 'all': ('All', '全部'),
 'guides': ('Guides', '指南'), 'weapon': ('Attacks', '攻击'),
 'function': ('Functions', '功能'), 'signal': ('Signals', '信号'),
 'usage': ('Usage', '用途'), 'settings': ('Settings', '设置'),
 'example': ('Example', '操作示例'), 'troubleshooting': ('Troubleshooting', '排查'),
 'defaults': ('Factory defaults / limits', '初始默认值 / 范围'),
 'numeric': ('%s: default %s; range %s–%s', '%s：默认 %s；范围 %s–%s'),
 'choice': ('%s: default %s; options: %s', '%s：默认 %s；可选：%s'),
 'editor': ('%s: open its editor', '%s：打开对应编辑器'),
 'schema_note': ('Values below come from the module definitions, not your saved configuration. Time fields use seconds; other units follow their labels. Color rows have an RGB button: On disables presets and expands three 0–255 channels; Off collapses them and restores the preset, retaining custom values. Some fields appear only in applicable modes. Sound layers are edited in the sound timeline.', '下方读取模块定义，非当前存档值。时间字段以秒计，其余单位按标签。颜色行左侧RGB开启时禁用预设，展开红绿蓝三行0–255；关闭收起并恢复预设，自定义值保留。部分属性仅在对应模式显示，声音层在声音时间线编辑。'),
 'empty': ('No matching chapters', '没有匹配章节'),
 'revision': ('Content revision %s · read only', '内容修订 %s · 仅查看'),
 'timeline': ('Example action timeline (seconds)', '示例动作时间线（秒）'),
 'open': ('Manual', '操作手册'), 'help': ('Read this module’s manual', '阅读此模块说明')}
for key, pair in ui.items(): text(key, *pair)

def chapter(id, title, paragraphs, module=False):
    entry = {'id': id, 'title': 'dashboard.sablelife.type_' + id if module else text('chapter.' + id, *title), 'sections': {}}
    if module: entry['module'] = id
    for tab, pair in zip(tabs, paragraphs): entry['sections'][tab] = [text(id + '.' + tab, *pair)]
    entries.append(entry)

chapter('getting_started', ('Getting Started', '核心入门'), [
 ('Use the Heart to inspect and activate a connected creature. Creative authoring uses the dashboard; Release, available in the dashboard and on every Core settings page, returns the creature to a dormant editing state without dismantling its build.', '通过Heart查看及激活连接生命体。创造模式在面板编辑，模块面板及核心设置的每个属性页都提供解除按钮，使生命体回到休眠编辑状态，不拆散结构。'),
 ('Empty-hand right-click: inspect; in creative mode it reopens the last editor for this core (Virtual modules on first use). Sneak + empty-hand right-click: activate. Repeating activation does not restore HP or deactivate. Ordinary terrain is not automatically a creature body; assemble your intended body with Sable. Release is a creative authoring reset, not an ordinary pause: it ends runtime signals/binding and the current life identity while retaining configuration.', '空手普通右键：查看，创造模式回到该核心上次的编辑面板（首次为Virtual modules）。潜行+空手右键：激活。再次激活不会回血或停机。普通地形不会自动成为身体，请用Sable组装目标主体。Release是创造编辑重置而非普通暂停：结束运行信号/绑定及当前生命身份，保留配置。'),
 ('1. Prepare the connected Sable body with its Heart.\n2. In creative mode, empty-hand right-click the Heart. Configure modules and Core settings before activation.\n3. Close the menu; sneak + empty-hand right-click the Heart to activate.\n4. To edit locked settings, use dashboard Release or right-click the body/core with the Creative Release Tool, then reopen the editor.\n5. Check settings and markers before activating again.', '1. 准备带Heart的连接Sable主体。\n2. 创造模式空手右键Heart，激活前配置模块及Core settings。\n3. 关界面，潜行+空手右键Heart激活。\n4. 编辑锁定属性时使用面板Release，或用Creative Release Tool右键主体/核心，再打开编辑器。\n5. 检查属性和标记后再次激活。'),
 ('If editing buttons are gray while alive, Release before changing locked settings. Some live controls remain available. Release does not fire death loot and does not recover material already removed by completed cleanup. Holding a block can disguise the Heart instead of opening its empty-hand interface.', '存活时编辑按钮灰色，先Release再修改锁定属性；部分实时控制仍可用。Release不触发死亡掉落，也不能恢复已清理材料。手持方块可能伪装Heart，而不是打开空手界面。')])
chapter('simple_start', ('A Simple Start', '简单起步'), [
 ('Purple modules handle signals, red modules attacks, yellow modules functions. Search localized or English names and stable IDs. Reading this manual does not execute abilities or change settings.', '紫色为信号、红色为攻击、黄色为功能。可搜索本地化名称、英文名称及稳定ID。阅读手册不会执行技能或修改配置。'),
 ('Modules must be enabled and their triggers satisfied. Required markers must remain connected. Core modules and Wireless redstone have no-Mark exceptions. Life Core uses life activation. Redstone Core supports its control/sound whitelist on an assembled unique-core body without life activation.', '模块需启用且满足触发。必需标记需保持连接。核心模块及无线红石存在无需Mark例外。生命核心需激活生命；红石核心在已组装且唯一核心的主体上运行控制/声音白名单，无需生命激活。'),
 ('1. Open Virtual modules and + Add module.\n2. Choose a module and adjust its settings.\n3. Click Mark area/origin where required and select its body face or two corners.\n4. Preview, choose a trigger, then activate the creature.\n5. Open ? for module-specific help.', '1. 打开Virtual modules，点击+ Add module。\n2. 选择模块并修改属性。\n3. 需要时点击Mark area/origin，选择主体面或两个角。\n4. Preview，选择触发后激活生命体。\n5. 点击?查看该模块说明。'),
 ('During marking, Shift + right-click in air clears the current mark. Esc or a sneak-click on a block cancels without clearing. A cleared required marker disables Preview. Renaming preserves module type; hover the list entry to identify it.', '标记中对空气Shift+右键清除当前标记。Esc或潜行点击方块只取消，不清除。清除必需标记后Preview禁用。改名保留类型，可悬停列表辨认。')])
chapter('basic_operations', ('Basic operation checklist', '基础操作清单'), [
 ('Start here before configuring individual modules.\n1. Getting Started: core inspection, activation and Release.\n2. Module management: add, rename, save, disable and delete.\n3. Mark system: point, area, direction, replace, cancel and clear.\n4. Preview: inspect geometry and troubleshoot unavailable buttons.\n5. Triggers and signals: choose activation and connect channels.\n6. Sound combinations: select and test layered audio.', '配置模块前先查这份清单。\n1. 核心入门：查看、激活及Release。\n2. 模块管理：添加、改名、保存、禁用及删除。\n3. Mark系统：单点、范围、方向、重选、取消及清除。\n4. Preview：查看几何范围及排查灰色按钮。\n5. 触发与信号：选择激活方式及连接频道。\n6. 声音组合：选择及试听多层音效。'),
 ('These chapters are in Guides at the start of the directory. Search their localized or English title, or IDs getting_started, simple_start, module_management, marking_system and preview_system. Opening a manual chapter is read only.', '这些章节位于目录前部的“指南”。可搜索中文/英文标题，或getting_started、simple_start、module_management、marking_system、preview_system等ID。打开说明只供阅读。'),
 ('1. Read Getting Started to enter the core editor, then A Simple Start for the module workflow.\n2. Add one module and save its basic settings.\n3. Read Mark system, select a valid origin and Preview.\n4. Choose its trigger.\n5. Activate the creature for a real test; return to the relevant troubleshooting tab if it fails.', '1. 按“核心入门”进入核心编辑器，再看“简单起步”学习模块流程。\n2. 添加一个模块，保存基础属性。\n3. 按Mark系统选择有效原点并Preview。\n4. 设置触发。\n5. 激活生命体实测，异常时查对应排查页。'),
 ('Separate these states: module enabled, marker valid, trigger active, and creature alive. A valid marker alone does not start an attack; Preview is not activation.', '区分四个状态：模块启用、标记有效、触发满足及生命体存活。有效标记不代表开始攻击，Preview也不是激活。')])
chapter('module_management', ('Module management', '模块基础管理'), [
 ('Manage virtual modules inside the Heart rather than placing a separate physical block for every ability. Each entry retains its type even after renaming.', '在Heart内管理虚拟模块，不必为每种能力单独放实体模块方块。改名后仍保留模块类型。'),
 ('+ Add module opens a separate catalog with All, Signals, Attacks, Functions and Presets. Select an entry and click Load modules, or double-click to add it. Search by localized or English name and ID. Rows fill downward before continuing in the next column; bottom arrows change pages. Use the arrows beside Add module to reorder existing modules, or the preset arrows to reorder personal favorites. Preset Delete requires two clicks and is disabled for built-in modules. Enter a name or number and press its checkmark to apply; choice buttons send their changes when selected. Enable/Disable controls an existing module without deleting its settings. Delete uses a second confirmation click. Language, left of Density, switches Minecraft between English and Simplified Chinese without restarting, with a brief resource reload. The language selection is saved. Density adjusts text and spacing; arrows page the module and property lists. Mouse wheel applies numeric edits immediately: counts/power/whole-block detection ranges use 1, angles use 5, and small sizes/motion retain decimal precision.', '+ Add module打开独立模块选择页，顶部可选全部、信号、攻击、功能及预设。单击选中后点击添加所选模块，或双击直接加入；可按中文或英文名称、ID搜索；每列从上到下排满后继续下一列，底部箭头翻页。添加模块旁的上下箭头调整已有模块顺序，预设页的专用上下箭头调整收藏顺序。删除预设需连续点击两次，内置模块不允许删除。输入名称/数值后点击对应勾保存；选项按钮切换时发送修改。Enable/Disable保留配置开关模块。Delete需二次确认。显示密度左侧的语言按钮可直接切换英文或简体中文，短暂重载资源后立即生效，无需退出世界或重启，且会保存Minecraft语言设置。Density调整文字/间距，箭头翻模块及属性页。数值框滚轮即时应用：次数/强度/整格检测距离每格1，角度每格5，小尺寸和运动参数保留小数精度。'),
 ('1. Click + Add module, select a type and click Load modules, or double-click it.\n2. Select the new list entry. Enter a useful name and click its checkmark.\n3. Set numeric fields with their checkmarks and select mode buttons.\n4. Hover a renamed entry to confirm its original type; use ? for help.\n5. Disable to keep it for later, or click Delete and confirm if removing it.', '1. 点击+ Add module，选择类型后点添加所选模块，或双击直接加入。\n2. 选新条目，输入易辨认名称并点勾。\n3. 数值用对应勾保存，模式用按钮切换。\n4. 悬停改名条目确认原类型，?查看说明。\n5. 暂停使用选Disable保留，移除则Delete并确认。'),
 ('Red input text indicates invalid values; use the displayed limits. A renamed module is still the same referenced module. Disabling/deleting a required Move set action can make its whole Move unavailable. Module enabled does not mean the creature is activated or its trigger is satisfied.', '输入变红表示数值无效，按显示范围设置。改名不改变引用身份。禁用/删除Move set必需动作可能使整Move不可用。模块启用不等于生命激活或触发满足。')])
chapter('marking_system', ('Mark system', 'Mark标记系统'), [
 ('Mark connects a virtual ability to a body point, face or area. Ordinary marks follow the marked body position and rotation. Arena is an exception: its marked center stays fixed in world space. Marking changes configuration, not the physical blocks.', 'Mark把虚拟能力连接到主体点、面或范围。普通标记跟随主体位置/旋转；Arena例外，其中心固定于世界。标记修改配置，不修改实体方块。'),
 ('Point: choose one connected body surface; the face supplies the marked direction. Area: Melee and Particle Area use two block corners on the SAME rigid body, up to 32 blocks per axis including corners. Connected articulated limbs are not necessarily the same rigid body. Particle Area and point patterns store marks separately. Navigation asks for a horizontal face toward the construct front. Arena allows a terrain/body point as a fixed center. Core modules do not need Mark; Wireless redstone may use external output without one.', '单点：选连接主体表面，点击面提供标记方向。范围：Melee及Particle Area选同一刚体两个方块角，每轴含端点最多32格。有关节连接的肢体不一定属同一刚体。Particle范围与单点分别保存。Navigation要求朝主体正面的水平侧面。Arena可选地形/主体点作为固定中心。核心模块无需Mark，无线红石可无Mark使用外部输出。'),
 ('1. Select the module, then click Mark area/origin; the menu closes and a selection hint appears.\n2. For a point, right-click the intended body face. For an area, right-click the first and second corners on one rigid body. Successful selection returns to the dashboard.\n3. Check marker status, then Preview the direction/volume.\n4. To replace a mark, click Mark area/origin again and finish the new selection.\n5. To cancel: Esc, or sneak-right-click a BLOCK. The previously saved mark remains.\n6. To CLEAR: enter marking again, aim into AIR and sneak-right-click. Saved marks for the current mode are cleared and the dashboard reopens.', '1. 选模块并点Mark area/origin，界面关闭并显示选择提示。\n2. 单点右键目标主体面；范围依次右键同刚体两个角。成功后回到面板。\n3. 检查标记状态，Preview方向/体积。\n4. 重选：再点Mark area/origin，完成新选择。\n5. 取消：Esc，或潜行右键“方块”，保留原已保存标记。\n6. 清除：再次进入标记，对准“空气”潜行右键，清除当前模式已保存标记并返回面板。'),
 ('Clearing only works during an active mark-selection session and when the server ray hits no block within reach. Looking at a block while sneaking cancels instead. A wrong body or oversized second corner is rejected; finish a valid selection or cancel. Selection expires after two minutes, or if permissions/configuration change. Destroyed/disconnected marked parts invalidate required modules; clearing a required mark returns to Not marked with Preview disabled. For particles, clearing Area does not erase the separately stored point mark.', '清除只在正在选择标记时有效，服务器视线在交互距离内不能命中方块。潜行对方块右键只取消。错误主体或过大第二角会拒绝，请重选有效点或取消。选择两分钟超时，权限/配置变化也会取消。标记部位损毁/脱离使必需模块失效；清除必需标记回到Not marked，Preview禁用。Particle清除Area不会清除另存单点。')])
chapter('preview_system', ('Preview and marker status', 'Preview预览与标记状态'), [
 ('Preview inspects configured origin, direction, volume or path before a real activation. Geometry previews do not execute the attack or move the creature. Particle previews can display decorative particles.', 'Preview在实际激活前检查原点、方向、体积及路径。几何预览不会执行攻击或移动生命体，粒子预览可显示装饰粒子。'),
 ('Ordinary marker previews last about five seconds and are sent only to the requesting player. A valid marker is not a trigger. Not marked, missing/disconnected body parts and unavailable permissions can disable Preview. Some core/no-Mark modules have dedicated editors or no marker preview. Wireless redstone can output externally without Mark even though a marked-output preview is unavailable.', '普通标记预览约五秒，仅发给操作玩家。有效标记不是触发。未标记、部位缺失/脱离或权限不满足可禁用Preview。部分核心/无需Mark模块使用专用编辑器或无标记预览。无线红石可无Mark外发，即使标记输出预览不可用。'),
 ('1. Apply settings and complete the required mark.\n2. Click Preview; inspect the front face, area or movement path in the world.\n3. Reopen the dashboard and adjust direction, Start distance, angles or range if needed.\n4. Repeat Preview, then separately activate the creature and satisfy its trigger for a real test.\n5. For sounds or Core death/vanish effects, use their own Preview controls.', '1. 保存属性，完成必需标记。\n2. 点Preview，在世界查看正面、范围或移动路径。\n3. 重开面板，按需调方向、Start distance、角度/距离。\n4. 再Preview，之后另行激活生命及满足触发实测。\n5. 声音及Core死亡/消失效果使用各自Preview。'),
 ('A gray Preview does not by itself mean a no-Mark module cannot run. Check whether that module requires Mark. Linear movement red path/destination means collision, not a trigger error. For area marks, compare the whole rotated volume rather than only its center. Effect previews are visual/audio demonstrations; death-effect preview is not actual creature death.', 'Preview灰色不代表无需Mark模块不能运行，先确认该模块要求。直线移动红色路径/终点表示碰撞，非触发错误。范围标记需检查整个旋转体积，不只是中心。特效预览是视听演示，死亡效果预览不是真正死亡。')])
chapter('core', ('Core settings', '核心设置'), [
 ('Configure health, regeneration, protection, death/vanish effects and adaptive defense for the whole creature. Death XP offers Points (0–30,970) or Levels (0–100). Levels drops a level reward orb: its collector gains the specified levels directly, as with /experience add levels, rather than receiving fixed XP points. Display-unit conversion still uses cumulative XP from level zero; applying a whole-level value changes the amount. Maximum health scrolls by 5 HP; XP by 1. Percentage regeneration defaults 0%, range 0–100%, scroll ±0.1. Total HP healed per second is fixed regeneration plus maximum health × percentage / 100; max HP 2000 with fixed 10 and 2% heals 50 HP each second. Both obey the same damage-reset quiet delay and never revive dying/dead creatures. Whole-body loot Back returns to Modules.', '配置整个生命体的生命、回血、保护、死亡/消失效果及自适应防御。死亡经验可选Points（0–30,970）/Levels（0–100）。Levels掉等级奖励球，拾取者直接增加指定等级，等同experience add levels，非固定点数奖励。切换显示单位仍按从0起累计点数换算，应用整级数值才修改数量。最大生命滚轮每格5 HP，经验每格1。每秒百分比回血默认0%，范围0–100%，滚轮±0.1；每秒总回血为固定量加最大生命值×百分比/100，例如最大生命2000、固定10、2%时每秒恢复50点。两者共用受伤后重置的回血延迟，不复活死亡/死亡倒数中的生命体。Whole-body loot的Back返回Modules。'),
 ('Void death height defaults to the current dimension’s minimum build Y (Overworld −64; Nether/End 0). It tests the living Life Core’s world-space center Y, not storage coordinates or a bedrock block search. Strictly below forces death through armor/adaptive defense. Set an integer −2048 to 2048 on the protection page; scroll ±1, right-click Apply to restore the dimension default. Dormant bodies and Redstone Cores are unaffected. Death delay is limited to 0–60 s. Names support &0–&f colors, &l bold, &o italic, &n underline, &m strikethrough, &k obfuscated, &r reset, and &#RRGGBB colors. Example: &c&lKilling Machine. Codes count toward the 64-character limit. Module direct kills announce the styled core name; unnamed cores announce block. Projectiles retain their launch name through save/load. Later environmental, fire-tick and status-effect deaths retain vanilla attribution.\n\nDeath effects play at death; vanish effects after Death delay. Death/limb cleanup discards directly referenced CBC mounted cannon and Create mechanical-bearing contraption entities when their controller has registered ownership and a death/part job; this includes supported addon payloads, Neo Warfare compact mounts and radar bearings. Ordinary disassembly and unrelated controllers remain unchanged. Force chunk loading defaults Off; On keeps the active/dying Life Core and connected Sable limbs loaded, following their occupied world chunks. Off, Release, core removal or finished cleanup releases its tickets. Caps: 256 target chunks per creature, 1024 server-wide. Each stage has one primary sound mix. Restore, left of Preview, resets only that stage’s effect and audio defaults. Adaptive defense defaults off: threshold 100 HP/s, maximum 80%, window 1 s. Damage is measured after armor and before adaptive reduction. At sustained 200 DPS the example approaches 50% reduction; 1000 DPS is limited to 80%. Threshold is not a hard DPS cap; maximum is not constant armor; window is not invulnerability.', '虚空死亡高度默认当前维度最低建造Y（主世界−64，下界/末地0），按存活生命核心的世界中心Y判定，不使用存储坐标或寻找基岩方块。严格低于时绕过装甲/自适应减伤强制死亡。保护页可设−2048至2048整数，滚轮±1，右键应用恢复维度默认。休眠主体及红石核心不受影响。Death delay限制0–60秒。名称支持&0–&f颜色、&l粗体、&o斜体、&n下划线、&m删除线、&k随机字符、&r重置及&#RRGGBB颜色。例如&c&lKilling Machine为红色粗体，格式代码计入64字符上限。模块直接击杀显示带格式的核心名称，未命名显示block；弹射物在保存/重载后仍保留发射时的名字。后续环境、持续燃烧及状态效果死亡保留原版归属。\n\n死亡效果在死亡瞬间播放，消失效果在Death delay后播放。死亡/部位清理会在控制器有登记归属及死亡/部位任务时，清理其直接引用的 CBC 挂载炮体和 Create 机械轴承运动结构，包含已验证的附属炮体、Neo Warfare 紧凑炮台和雷达轴承。普通拆卸和其他独立控制器保留原行为。强制区块加载默认Off，On维持存活/死亡倒数中的生命核心及连接Sable肢体加载，随占用世界区块更新。Off、Release、核心移除或清理完成时释放自身票据。每生命体最多256目标区块，全服务器1024。每阶段仅保留一个主声音组合。Preview左侧Restore仅还原当前阶段的特效与音效默认值。自适应防御默认关：阈值100 HP/s，上限80%，窗口1秒。统计装甲后、自适应减伤前伤害。持续200 DPS示例趋近50%减伤；1000 DPS受80%上限限制。阈值非硬封顶，上限非固定装甲，窗口非无敌时长。'),
 ('1. Open Core settings; configure health and regeneration.\n2. On the death and vanish pages, choose patterns, particles and sound mixes separately. Preview both stages; Preview closes the menu so you can view the effect. Reopen the same core to return to the last settings page.\n3. Open Defense settings if sustained high DPS protection is desired. Begin with 100 / 80 / 1.\n4. Activate and compare isolated hits with sustained attacks.', '1. 打开Core settings，设置生命和回血。\n2. 分别在死亡/消失页设置样式、粒子及声音组合，分别Preview；预览退出界面以观察效果，重开同一核心回到上次设置页。\n3. 需要抵抗持续高DPS时开启Defense，先用100 / 80 / 1。\n4. 激活，比较单次与持续伤害。'),
 ('Adaptive reduction recovers smoothly after recent damage expires. Physical core removal is not an ordinary defended hit. Changing defensive configuration clears its temporary damage statistics. See Death delay and chunk unloading for leaving the area or closing the world.', '近期伤害过期后减伤平滑恢复。拆除实体核心不是普通受防御命中。修改防御配置会清除临时伤害统计。离开范围或关闭世界的行为详见死亡延迟与区块卸载。')])
chapter('death_unloading', ('Death delay and chunk unloading', '死亡延迟与区块卸载'), [
 ('Death delay is tracked by a world-owned death job, independently of the core block ticking. Leaving the area does not revive a dying creature or restart its delay.', 'Death delay由世界级死亡任务记录，不依赖核心方块持续Tick。离开范围不会使濒死生命体复活，也不会重置延迟。'),
 ('While the server continues ticking, death countdowns continue even if the creature chunks are unloaded or a multiplayer player logs out. With Force chunk loading Off, unloaded blocks are not force-loaded: removal and loot/XP settlement wait until their required chunks are loaded. With On, the active/dying connected body stays loaded and necessary death reward chunks are held until settlement, within loading limits. Exiting a single-player world, shutting down the server or pausing its ticks saves/freezes the remaining delay; real offline time is not deducted.', '服务器持续推进Tick时，即使生命体区块卸载或多人玩家下线，死亡倒数仍继续。强制加载Off时不会强制加载未加载区块，清除方块及掉落/经验结算等待所需区块加载。On时在加载上限内维持存活/死亡倒数中的连接主体，以及结算所需的死亡奖励区块。单人退出世界、服务器关闭或Tick暂停时，保存/冻结剩余时间，不扣除真实离线时长。'),
 ('Set Death delay to 60 s. After death, stay for 20 s, then teleport away for 45 s while the server continues ticking. On return the delay has expired; pending loaded-body cleanup/settlement proceeds instead of restarting a 40 s timer. If you closed the single-player world after the first 20 s, reopening resumes about 40 s, regardless of real time away.', 'Death delay设60秒：死亡后等20秒，传送离开45秒且服务器持续运行。回来时延迟已到期，继续处理加载后的清理/结算，不会再从40秒倒数。若前20秒后退出单人世界，则重开后从约40秒继续，与真实离线时长无关。'),
 ('Void-height death uses the same death effects, delay, cleanup and loot/XP locations; it does not rescue or move rewards to safe ground. Height detection requires the living core to tick. An unloaded corpse may remain saved until it can be cleaned safely; this is pending cleanup, not renewed life. Large bodies can take several ticks to clean. Loading applies to world-space body coverage, not only the core block or Sable storage coordinates. The settings page reports target chunk count or an exceeded limit. Loot/XP settlement is recorded to avoid duplicate rewards. Chunk loading cannot make a stopped or paused server continue ticking.', '虚空高度死亡沿用同一死亡特效、延迟、清理和掉落/经验位置，不救回主体或把奖励搬到安全地面。高度检测需要存活核心推进Tick。未加载尸体可能暂时保留在存档，直到可安全清除；这是待清理，不是重新存活。大型主体可能分多个Tick清理。加载按主体世界空间覆盖范围计算，不只核心一格或Sable存储坐标；设置页显示目标区块数量或超过上限。掉落/经验结算会记录，避免重复奖励。区块加载无法让已停止或暂停的服务器继续Tick。')])
chapter('server_limits', ('Server resource limits', '服务器资源限额'), [
 ('These limits bound unusually large configurations. They do not change ordinary attack damage, signed part modifiers or action timing. Use the server-owned configuration when hosting multiplayer worlds.', '这些限额用于约束异常庞大的配置，不改变正常攻击伤害、部位伤害修正或招式时间。多人世界由服务器管理员设置。'),
 ('The world serverconfig/sablelife-server.toml controls newly authored wireless channels (default 256), particle points per player/tick (8192), loaded Sable Life projectiles per dimension (8192) and per creature (2048), shared death cleanup blocks per server tick (256), and collision checks per dimension/tick (8,388,608). Existing saved channels and their numbers are retained. Saved or already flying projectiles are not deleted to enforce a new-spawn limit.\n\nAt a collision budget limit, movement waits and reports its state; terrain blocking still stops it normally. Cosmetic emission can be reduced at the particle limit. Death cleanup is shared and rotated between pending jobs; unloaded blocks remain protected until they can be cleared.', '世界目录中的serverconfig/sablelife-server.toml设置新建无线频道数量（默认256）、每位玩家每Tick粒子点数（8192）、每个维度已加载弹射物数量（8192）、每个生命体新弹射物数量（2048）、全服务器每Tick死亡清理方块数量（256）以及每个维度每Tick碰撞检查次数（8,388,608）。旧存档的频道和编号保留。达到新生成限额时不会删除已经飞行或从存档加载的弹射物。\n\n碰撞预算不足时位移等待并显示状态，实际地形阻挡仍正常停止。粒子限额可能减少视觉输出。死亡清理任务共享预算并轮流处理，未加载方块继续保持保护，直到能够清理。'),
 ('Use a modest test machine before increasing limits. Monitor server tick time and observer traffic with the actual mods and player count. Limits are not a promise of a particular TPS or supported creature count.', '提高限额前先用适量机器测试，并在实际模组和玩家人数下观察服务器Tick耗时及网络流量。限额不代表保证某个TPS或可运行的生命体数量。'),
 ('Only administrators can author or import command modules. A blueprint placement API has no player identity, so imported command modules require administrator approval through the command editor before they run. Opening and saving an ordinary module preset does not grant command permission. Editing requests and complex imports are rate-limited; retry after a short pause if a burst is rejected.', '命令模块只允许管理员编写或导入。蓝图放置接口没有玩家身份，因此蓝图中的命令模块需要管理员通过命令编辑器确认后才能运行。保存或打开普通模块预设不会授予命令权限。编辑请求及复杂导入有频率限制；连续操作被拒绝时，稍等后再试。')])
chapter('triggers', ('Triggers and signals', '触发与信号'), [
 ('Triggers decide when enabled modules activate. Hurt can control either an individual module or a Move set with a fixed combination.', '触发决定启用模块何时激活。Hurt可控制单模块，或控制固定组合的Move set。'),
 ('Always follows active life, or an operational assembled Redstone Core. Mark redstone reads a marked input. Internal wireless uses body-local channels; external wireless uses red/blue frequency items. Move set actions are scheduled by their controller. Hurt has separate response, signal duration and cooldown settings. Attack Interval and sound Start are separate clocks.', 'Always跟随生命激活，或已组装且可运行的红石核心。Mark红石读取标记输入；内部无线用主体内频道，外部无线用红蓝频率物品。Move set动作由控制器调度。Hurt另有响应、信号时长及CD。攻击Interval和声音Start分别计算。'),
 ('1. Select Trigger when hurt on an independent attack.\n2. Open its hurt settings and choose response, duration and cooldown.\n3. For a combination, instead set action modules to move set and the controlling Move set to Hurt.\n4. Independent Hurt modules may run alongside that combination.', '1. 独立攻击选Trigger when hurt。\n2. 设置受伤响应、时长及CD。\n3. 组合则内部动作设move set触发，控制Move set设Hurt。\n4. 独立Hurt模块可与组合并行。'),
 ('A very short signal can allow only one shot or hit. Hurt cooldown throttles new responses, not individual attack hits. Do not treat an internal channel number as an external item frequency.', '信号太短可能仅一次攻击。受伤CD限制新响应，不是每次攻击命中。内部频道数字不是外部物品频率。')])
chapter('sound_timeline', ('Sound combinations', '声音组合'), [
 ('The shared sound editor supports multiple layers for modules, death, vanish and BGM.', '共用声音编辑器支持模块、死亡、消失及BGM多层组合。'),
 ('Each layer has Start, Pitch, Volume, Range and an optional playback limit. Limit 0 allows natural effects playback or native BGM looping; positive values cut off only that layer. Dashed natural tails are not measured file durations. Mouse wheel over Start, Pitch and Volume adjusts by 0.1; Range and Limit adjust by 1.', '每层有Start、Pitch、Volume、Range及可选截断。Limit 0允许音效自然播放或BGM原有循环；正数仅截断该层。虚线尾部不是测量的文件长度。鼠标悬停Start、Pitch、Volume滚轮每格±0.1，Range、Limit每格±1。'),
 ('1. Open a sound button; search the left library. MC and OGG tools are inside this page.\n2. Double-left-click a library or selected sound to listen. Right-click a library sound to add it, then add another layer.\n3. Set starts to 0 and 0.4 s; adjust each pitch/volume.\n4. Preview one layer or the mix, stop and return.', '1. 点击音效按钮，搜索左侧库；MC、OGG入口在页内。\n2. 双击左侧库或已选声音可试听；右键库中声音添加，再加一层。\n3. 分别设0和0.4秒开始，调整音调/音量。\n4. 试听单层或组合，停止后返回。'),
 ('Closing preview stops its queue. Effect tails may finish after an attack phase, but disabling/deleting their source cancels them. Custom OGG resources must be present on listening clients. Hearing range is not attack range.', '关闭试听停止试听队列。音效尾音可超过攻击阶段，禁用/删除来源会取消。自定义OGG需在听觉客户端存在。听觉范围不是攻击范围。')])
chapter('retaliation', ('Hurt counterattack', '受伤反击'), [
 ('Example: a fixed hurt-triggered combo plus an independent extra reaction.', '实例：受伤固定组合加独立额外反应。'),
 ('Hurt settings belong to the controlling Move set; scheduled actions use move set triggers. An independent extra action uses its own Hurt cooldown.', '受伤设置属于控制Move set，内部动作使用move set触发；独立额外动作使用自身Hurt CD。'),
 ('1. Add and mark an attack and Trigger sound.\n2. Set both to move set triggers and add them to one Move.\n3. Set the Move set to Hurt and choose a one-response mode and cooldown suitable for the sequence.\n4. Optionally add a separate marked Hurt attack.\n5. Damage once, then rapidly again; verify both response cooldowns.', '1. 添加并标记攻击及Trigger sound。\n2. 两者设move set触发，加入同一Move。\n3. Move set选Hurt，设置适合组合的单次响应及CD。\n4. 按需加独立标记好的Hurt攻击。\n5. 伤害一次再连续伤害，检查两套CD。'),
 ('A missing required action invalidates the whole reaction. Hurt Once ends the cancelled reaction instead of endlessly retrying it; a new hurt event is required.', '缺少必需动作使整套反击无效。Hurt Once取消后结束，不会无限重试，需新受伤事件。')])
chapter('survival_core', ('Redstone Core', '红石核心'), [
 ('A survival-craftable control core with a purple signal crystal and camouflage casing. It runs harmless redstone programs without activating life.', '可生存合成的控制核心，紫色信号菱形与可伪装外壳。无需激活生命即可运行无害红石程序。'),
 ('Supports Move set, Pulse sequence, Wireless redstone, Target sensor, Target alignment, Auto facing, Item display, Sound, Trigger sound, BGM and the Wireless page internal cycles/external RX/TX. Master controls output. Assemble the body first; exactly one core is allowed across all connected parts, including life cores. No attacks, commands or Hurt. Move set schedules only allowed control modules; HP conditions do not apply. Sound names and editors are shared: Hurt sound is disabled, and BGM runs on its trigger for nearby listeners instead of waiting for combat. Inactive combat settings remain stored for reuse with a Life Core.', '支持Move set、Pulse sequence、Wireless redstone、目标感应、目标对准、Auto facing、物品显示、Sound、Trigger sound、BGM及Wireless页内部循环/外部RX/TX。总开关控制输出。先组装主体，所有连接部分合计只能有一个核心，包含生命核心。不开放攻击、命令或Hurt。Move set仅调度允许的控制模块，不使用HP条件。声音名称及编辑器共用：受伤音效禁用，BGM按触发为范围内玩家播放，不等待战斗。禁用的战斗设置仍保存，方便生命核心复用。'),
 ('1. Craft one core: redstone block / redstone torch / redstone block; repeater / amethyst shard / comparator; redstone block / lever / redstone block.\n2. Place it in a body and assemble using the normal Sable assembly workflow.\n3. Empty-hand right-click to configure. Add Wireless redstone, mark an outlet or choose Frequency Item.\n4. Choose Always for continuous output, or connect an internal/external channel trigger. Use Master to pause. No life activation is needed.', '1. 合成一个核心：红石块/红石火把/红石块；中继器/紫水晶碎片/比较器；红石块/拉杆/红石块。\n2. 放入主体，按通常Sable流程组装。\n3. 空手右键设置，添加Wireless redstone，标记输出口或设置Frequency Item。\n4. 持续输出选Always，或关联内部/外部频道触发。总开关可暂停，无需生命激活。'),
 ('Not assembled, duplicate core or Master Off stops output. Newly placed duplicates are rejected; duplicates introduced by assembly, merge or reload suspend output until removed. Match frequency items and choose the correct trigger/channel. Copy and reload retain only the harmless whitelist.', '未组装、重复核心或总开关关闭会停止输出。直接放置重复核心被拒绝；组装、合并或重载引入重复时暂停输出，移除多余核心后恢复。检查频率物品及触发频道。复制与重载仅保留无害白名单。')])

# Usage reuses the existing module description. Settings/example/diagnosis are specific.
notes = {
 'move_set': ('Conditions filter distance, HP band and line of sight before Weighted / Priority selection. Forward reference defines facing. Cooldown limits reuse; Rest spaces moves. Rules and timing are owned entirely by Move set; no Move dispatcher is required. Existing saved Move set rules load automatically.\n\nEach Move set selects moves, tracks cooldowns and runs its timeline independently. When two controllers reference the same module, their active action windows are combined as an OR signal. The module keeps one runtime and its own interval; it is not duplicated, queued or restarted by the second overlapping controller. It remains triggered until all referencing action windows end.', '距离、HP比例及视线先筛选，再按权重/优先选择。Forward reference确定正面，Cooldown限制重复，Rest用于休息。条件与调度完全由Move set管理，无需Move dispatcher；现有Move set招式配置自动读取。\n\n多个自定义动作抽选各自选招、计时和冷却。同时引用同一模块时，动作窗口按“任一仍在激活”合并；模块只保留一份运行状态及自身间隔，第二个重叠窗口不会复制、排队或重新启动它。所有引用窗口结束后才解除该触发。', 'Create two marked attacks with move set triggers. Open Edit move set, add a Move and two actions; start the second at 0.5 s, then configure Conditions / rhythm.', '创建两攻击并标记，选move set触发，打开Edit move set，加Move及两动作，第二个0.5秒开始，再设Conditions / rhythm。', 'ANY required referenced action missing, disabled, disconnected or unmarked makes the whole Move ineligible. Running damage cancels remaining dispatch; other complete Moves continue. If all Moves fail, the controller waits. It never just skips the broken action. Wireless redstone and commands retain no-Mark exceptions.\n\nShared modules and channels are not reserved or isolated between controllers. For example, action windows 0–3 s and 2–5 s keep one shared module triggered continuously from 0–5 s. Use separate module instances and channels when independent behavior is needed. Overlapping sequence channel outputs combine by maximum power. Avoid conflicting assignments yourself; no automatic arbitration is applied.', '任一必需引用动作缺失、禁用、脱离或无标记，整条Move不可选。运行中损坏取消剩余调度，其他完整Move继续；全部无效则等待，不会仅跳过坏动作。无线红石及命令保留无需Mark例外。\n\n共用模块或频道不会自动预留、隔离或仲裁。例如两个窗口分别为0–3秒和2–5秒，同一模块会持续触发0–5秒，并沿用自身的间隔。需要独立行为时使用不同模块实例与频道。同频道的序列输出按最大强度合并；冲突由玩家自行规划避免。'),
 'wireless_redstone': ('Power controls strength; Hold follows activation, Pulse uses pulse duration. Faces selects all or marked face. Red/blue items define external frequency; ignore them for Mark-only output.\n\nReverse signal defaults Off. On swaps zero and configured power for both destinations. Hold outputs while idle and stops while triggered. Pulse normally outputs, interrupts for the configured pulse duration on a rising trigger, then restores output even if the trigger remains high. Disabled/invalid modules, dormant/dead cores and master Off always output zero.', 'Power为强度，Hold跟随激活，Pulse使用脉冲时长。Faces选六面或标记面。红蓝物品为外部频率，只用Mark可忽略。\n\n反转信号默认关闭。开启后两种输出同时交换0与设定强度。持续模式未触发时输出、触发时断开；脉冲模式平时输出，触发上升沿后断开指定脉冲时长，结束后恢复，即使触发仍保持高。模块禁用/失效、核心休眠/死亡或总开关关闭时始终输出0。', 'Configure Frequency Item to match an external receiver, or mark an output block. Choose Hold and trigger directly or through Move set.', 'Frequency Item与外部接收器匹配，或标记输出方块，选Hold后直接或经Move set触发。', 'Mark is optional, including inside Move set. With no marked or external destination it emits nothing. Other producers on the same block/frequency combine by maximum power and can mask an inverted low; use a dedicated output for interruption.', '包括Move set内Mark也是可选。没有标记或外部输出目标时不发信号。同一方块/频率的其他输出按最大强度合并，可能遮盖反转断开；断开用途应使用专用输出。'),
 'command': ('Impulse / Repeat / Chain determine behavior. Conditional requires the immediately preceding row to succeed in this pass. Repeat interval throttles repeat rows.', 'Impulse / Repeat / Chain控制类型。Conditional要求紧邻上一行本轮成功，Repeat interval限制重复行。', 'Open Edit commands, add a blank row, type say hi, use Tab and Save command. Choose Impulse, enable and trigger. Add a conditional Chain row to test dependencies.', '打开Edit commands，加空行输入say hi，Tab补全后Save command。选Impulse，启用并触发，可加条件Chain测试依赖。', 'Save does not execute. Check permissions/server command settings. Executes at the moving core without Mark.', '保存不执行，检查权限/服务器命令设置。在移动核心执行，无需Mark。'),
 'melee': ('Two marks define a volume. Start distance shifts it; horizontal/vertical angles rotate it and its offset direction around the center. Hit limit is per target per continuous activation. 0 = unlimited, still subject to Interval.', '两点定义体积，起始距离平移，水平/垂直角绕中心旋转体积与偏移方向。命中上限按每目标每次连续激活，0=无限，仍受Interval限制。', 'Mark two corners on the same body, set hit limit 3 and Interval, adjust offsets and Preview. Hold activation while a target enters/leaves.', '标记同主体两角，设命中上限3及Interval，调整偏移并Preview，持续触发让目标进出。', 'Leaving does not reset hit count; ending activation does. Hurt Once can be too short for repeated hits.', '离开不重置次数，结束激活才重置。Hurt Once可能不足重复命中。'),
 'flame': ('Speed controls outward travel, Width spread and Range reach. Start distance clears the muzzle. Particle opens the shared selector: normal/soul fire or mixed supported particle types, each with size and lifetime. Lifetime 0 covers the journey. Effect adds status effects on successful damage hits; Damage and Burn remain separate.', '速度控制外飞、Width扩散、Range距离，Start distance避开喷口。Particle打开共用选择页，可选普通/灵魂火或混合支持的粒子，各自设大小和寿命，0寿命覆盖行程。Effect在成功伤害命中时施加状态效果，Damage与Burn独立。', 'Mark the outlet, choose particles and size in Particle, then add Slowness with duration/level in Effect. Set Burn to 0 for no ignition, Preview, then trigger against a test target. Adjust Width moderately.', '标记喷口，在Particle选粒子/大小，在Effect加缓慢及持续时间/等级；不想点燃则设Burn为0，Preview后对测试目标触发，适度调整Width。', 'Particle size is not the damage hitbox. Short particle lifetime can cut the visual off early; 0 follows range/speed. Effects follow successful hits and the same interval. Existing blue-fire/size settings migrate automatically. Check direction and interval if intermittent.', '粒子大小不是伤害判定。短寿命会提前消失，0按射程/速度覆盖行程。Effect跟随成功命中及同一间隔。旧蓝火/大小自动迁移；断续时检查方向与Interval。'),
 'particles': ('Area uses two marks; Point/Line/Ring/Sphere use a separate single mark. Start distance offsets origin. Radius/length shapes it. Ring height 0 preserves one circle; positive height extends a hollow cylinder from the origin along the selected direction. Density is shared over its surface, without multiplying emission per layer. Outward/inward propagation expands or contracts radially at each axial section. Random/Even and sphere Inside/Surface select distribution. Density is per particle type; size/lifetime are in the particle editor. Line/Ring/Sphere Propagation can travel outward from center or inward from the endpoint/edge. Speed is blocks per tick; lifetime 0 covers the path. Motion trail fills body movement/rotation gaps; Only while moving controls emission timing.', 'Area两点，Point/Line/Ring/Sphere另存单点。起始距离偏移原点，半径/长度定义形状；圆环高度0保留单圈，正数沿所选方向从原点延伸为空心筒壁。密度分布于整个筒壁，不逐层倍增，向外/反向传播在每个轴向截面径向展开/收拢。Random/Even及球内/表面控制分布。密度按每种粒子，大小/寿命在粒子编辑器。Line/Ring/Sphere的Propagation可从中心向外或从末端/外缘回中心。速度单位格/游戏刻，寿命0覆盖路径。Motion trail补齐主体移动/旋转间隙，Only while moving控制发出时机。', 'Choose Sphere, mark one point, set radius, Random and Inside, then Preview. Switch to Area and mark two corners; switching back retains the point mark. Line supports placed or spray modes.\n\nFor a tube, choose Ring, radius 2, Ring height 8, direction Up and density 32. Preview the three circular sections and side edges. Increase density for a less sparse wall.', '选Sphere标记一点，设半径、Random和Inside并Preview。切Area标两角后切回，单点仍保留；Line有放置/喷射模式。', 'Clear affects only the current mark mode. High density/many types cost more particles. Native friction/gravity do not shorten controlled travel. A custom lifetime shorter than the journey still cuts it off.', '清除仅影响当前模式。高密度/多种粒子增加负载，受控路径不受原版阻力/重力缩短，较短自定义寿命仍会提前结束。'),
 'signal_turn': ('Mark one front face. Per-axis turn speed at strength 15 defaults to 120 degrees per second, range 0–720, scroll ±5. Each of left/right, up/down and clockwise/counterclockwise roll has its own channel and choice of internal wireless output or external wireless receiver. Channel 0 disables that direction. Internal channels must provide an enabled waveform/program output; external channels must be enabled receivers.\n\nTurn speed is proportional to signal strength: speed × strength / 15. At 120 degrees/s, 15 gives 120, 7 gives 56 and 0 stops. Opposite signals subtract on their axis: left 15 and right 7 give left 64 degrees/s. Multiple axes can rotate together; their combined rotation speed can be higher than the speed of one axis.', '标记一个正面。每轴满信号转速默认120度/秒，范围0至720，滚轮±5。左/右、抬头/低头、顺/逆时针侧转各有独立频道，可选择内部无线输出或外部无线接收，频道0关闭该方向。内部频道需要启用波形/程序输出，外部频道需要启用接收。\n\n转速按设定速度×信号强度/15变化。转速120时，15对应120度/秒，7对应56，0停止。同轴相反方向取信号之差：左15、右7时，向左64度/秒。多个轴可同时转动，组合后的总转速可能高于单轴转速。', '1. Add Signal turning and mark the machine front.\n2. Set speed 120 and left input to internal channel 1. Enable channel 1 in Program internal mode.\n3. Supply strength 7 to channel 1 to turn left at nominal 56 degrees/s; 15 gives 120.\n4. Bind right to channel 2. Equal left/right strengths stop yaw; a stronger right signal turns right.\n5. Configure up/down and roll only if needed, or use external receiver channels for your redstone control system.', '1. 添加信号转向并标记机器正面。\n2. 转速120，左转输入选内部频道1，无线频道1启用并设为程序内部。\n3. 给频道1强度7，名义向左转速56度/秒；强度15为120。\n4. 右转绑定频道2，左右强度相同时停止水平转向，右侧更强时向右转。\n5. 按需绑定抬头/低头和侧转，或使用外部接收频道连接自制红石控制。', 'Signal turning does not select or track targets. No net signal allows Auto facing to run if separately active. With net input, the first available Signal turning module controls rotation and pauses Auto facing, including when rotation is blocked. Linear movement has priority.\n\nCollision defaults On, using contact-deflated body bounds and the existing safe rotation sweep. Large machines may be limited below nominal speed; blocked axes are skipped while clear axes continue. Off ignores those blockers. Death, disable, invalid/lost marks and master Off stop module rotation. Keep front markers, channel modes and opposing signal strengths consistent.', '信号转向不选择或追踪目标。没有净转向信号时，另行激活的自动朝向可以运行；存在净输入时，第一个可用信号转向模块控制旋转并暂停自动朝向，即使旋转受阻。直线移动优先。\n\n碰撞默认开启，使用带接触余量的身体范围和现有安全旋转扫掠；大型机器可能低于名义转速，受阻轴跳过、其余安全轴继续。关闭后忽略这些阻挡。死亡、禁用、标记丢失/失效及总开关关闭会停止转向。确认正面、频道模式及相反方向强度配置一致。'),
 'linear_movement': ('Fixed distance is the legacy default: distance and horizontal/vertical angles steer movement.\n\nToward target selects the nearest eligible target within Target search range. The marked movement point stops N blocks before the target center; N is Stop before target. This is center distance, not a guarantee of collision-box clearance. At or within N, no movement is needed; no target means waiting. The target position is sampled when charging starts and is not updated to chase later movement. Horizontal mode fixes the endpoint X/Z while preserving current movement height; 3D mode fixes the complete endpoint. Creative players can be included. Use target height defaults Off: keep current movement-point height and use a horizontal stopping gap. On uses the recorded target height and a full 3D stopping distance.\n\nTarget mode replaces fixed distance/direction/angle settings without rotating the construct. Teleport and Travel keep their existing collision/loaded-area checks. Charge, departure and arrival have separate effects/sounds. Teleport checks destination; Travel checks terrain by default. Force movement defaults Off. On skips terrain/body collision prechecks, while retaining loaded-destination/world-bound checks. Forced Travel follows planned translation despite physics pushback. Normal physics still applies after completion.', '固定距离是旧默认模式，距离和水平/垂直角控制方向。\n\n朝目标移动选择搜索范围内最近的有效目标。标记移动基点会停在目标中心前方N格，N由目标前方预留距离设置；这是中心距离，不保证碰撞箱之间有同样空隙。已经在N格以内时不移动，没有目标则等待。蓄力开始时记录目标位置，不追踪其后续移动；水平模式固定终点XZ并保持当前高度，三维模式固定完整终点。可选择包含创造玩家。使用目标高度默认关闭：保持当前移动基点高度，N按水平距离计算；开启时使用记录的目标高度，N按三维距离计算。\n\n目标模式替代固定距离、方向及角度属性，仅移动、不自动转向。传送/连续移动仍检查原有碰撞及已加载范围。蓄力/离开/出现独立效果及声音。传送检查终点，Travel始终检查地形并安全停止。', 'Mark a starting face, choose Teleport with short distance and zero angles, Preview on flat ground. Switch to Travel and configure speed for gradual movement.\n\nFor target movement, select Toward target, choose target type and search range, then set Stop before target to 2. A target 10 blocks from the mark gives an 8-block displacement. Preview before triggering; the same target mode works with Teleport and Travel.', '标记起始面，Teleport短距离和0角度，在平地Preview；切Travel设速度渐进移动。\n\n目标移动示例：选择朝目标移动，设置目标类型和搜索范围，目标前方预留距离设2。目标与标记点相距10格时，位移8格；先预览再触发，传送和连续移动都可使用目标模式。', 'Small contact tolerance permits touching ground, not embedding in walls. Large bodies need clearance for all parts. Movement checks each connected rigid body’s contact-adjusted enclosing box against terrain collision shapes and other Sable bodies’ enclosing boxes. Empty corners in rotated/sparse bodies can therefore block before a real body voxel touches. Travel approaches the closest allowed position then stops; Teleport cancels if its required path or destination check fails. Ordinary living-entity hitboxes are not included in this precheck. Target stop distance does not override collision.\n\nTarget stopping distance measures the marked point to target center, not two collision-box surfaces. Once movement completes, ordinary physics resumes; this module does not hold the construct in the air or lock its position.', '小接触容差允许贴地，不允许嵌墙，大主体需所有部分净空。移动预检使用每段连接刚体的包围盒（带接触容差），与地形碰撞形状及其他Sable主体包围盒比较；旋转或稀疏身体的空角也可能提前挡住。连续移动接近判定允许的最近位置后停止；传送的路径或终点检查失败则整次取消。普通生物/玩家判定箱不属于这项预检，目标预留距离不能覆盖碰撞限制。\n\n目标预留距离按标记点到目标中心计算，不是两碰撞箱表面的间隙。移动完成后仍受正常物理影响，本模块不会悬停或锁住位置。'),
 'arena': ('Radius uses a fixed horizontal center. Countdown starts when the creature leaves, not players. Nearby-player death defaults on; force return/full health defaults off and takes precedence when on. No-nearby-player return is separate.', '半径取固定水平中心。生命体出圈才倒计时，非玩家。附近玩家死亡默认开；归位满血默认关，开启优先。无附近玩家归位另算。', 'Mark center and set radius. Disable nearby-player death while testing; choose force return if wanted. Move the creature out and observe.', '标记中心设半径，测试先关附近玩家死亡，按需开归位，把生命体移出观察。', 'Center stays fixed in world; return preserves height. Check nearby survival-player range for punishment.', '中心固定世界，归位保留高度。惩罚需检查附近生存玩家范围。'),
 'homing': ('Formation and fan rotations use the marked face. Offset/height position hovering shells; deploy and charge precede launch. Target filters, tracking and lifetime control pursuit.', '阵型/旋转按标记面，偏移/高度定位悬浮弹，部署蓄力后发射，目标/追踪/寿命控制追击。', 'Choose Arc (n), both rotations 0; view from the marked face front. Set targets and Preview before triggering.', '选Arc (n)，两旋转0，从标记面正面看，设目标并Preview后触发。', 'Above-view appearance differs. Verify marked face before changing rotation; check target filters.', '俯视外观不同，先确认标记面再改旋转，检查目标过滤。'),
 'mortar': ('Aim, target, speed and launch angle define the arc. Warning color applies from its first frame. Explosion/block damage are separate.', '瞄准/目标/速度/发射角定义弧线，预警颜色首帧生效，爆炸/方块伤害独立。', 'Mark launch face, choose target mode and a non-red warning color, then trigger in open terrain.', '标发射面，选目标和非红预警色，在空旷处触发。', 'Check arc clearance/target range for misses. A large hitbox may need more Start distance.', '偏离时检查弧线净空/目标距离，大判定可能需更多起始距离。'),
 'navigation': ('Target range, forward reference, tracking, dead zones and lock govern navigation signals. Reverse redstone directions swaps left/right, up/down and front/back while preserving strength. The player designs the physical movement/aiming mechanism.', '目标距离、正面、追踪、死区和锁定控制导航信号。反转红石信号互换左右/上下/前后，强度不变；实体机械移动/瞄准由玩家设计。', 'Mark reference, choose targets and configure output connections; wire them to your own turning mechanism and test both axes.', '标记参照，选目标和输出连接，接自己的转向机械，测试两轴。', 'This outputs signals; use Linear movement for direct travel. Verify wiring and mechanical design.', '本模块输出信号，直接移动用Linear movement；检查线路和机械设计。'),
 'damage_accumulation': ('Threshold counts actual health lost after part modifiers and adaptive defense. Immunity and zero-damage hits do not count; healing does not subtract accumulated damage. Threshold range 1–1,000,000, default 100, scroll ±1. Pulse/interruption duration defaults to 1 second. Reaching the threshold latches exactly one pulse. Excess damage and every hit during output are ignored. After the pulse completes, reset to zero and start the next damage cycle.\n\nInternal output uses an enabled Program internal or Program transmitter channel; channel 0 disables that destination. External Create output uses the red/blue frequency items and can operate alone or alongside internal output. Reverse Off normally outputs zero and emits configured strength at threshold. Reverse On normally outputs configured strength and goes low for the pulse duration at threshold.', '阈值统计部位修正及自适应防御后的实际扣血，免伤和零伤害不累计，回血不减累计值。阈值范围1至1,000,000，默认100，滚轮±1。脉冲/断开时长默认1秒。达到阈值后只输出一次，超出阈值及输出期间的所有伤害均不再累计；输出结束后清零，重新开始累计。\n\n内部输出请选择已启用的程序内部或程序发射频道，频道0关闭该输出。外部Create输出使用红蓝物品频率，可单独或与内部同时使用。反转关闭时平时为0，达到阈值后输出指定强度；反转开启时平时输出，达到阈值后断开指定时长。', '1. Add Damage accumulation trigger, no mark needed.\n2. Set threshold 100, channel 1, power 15 and duration 3 s. Enable Wireless channel 1 in Program internal mode.\n3. Set Move set to Trigger: internal wireless, channel 1. Turn Reverse signal On on the accumulator.\n4. Deal 30, 40 and 50 actual damage: one 3-second interruption begins; the extra 20 damage is discarded. Hits during that interruption do not count. After it ends, accumulation restarts at zero. When Move set loses its trigger, it cancels its current scheduling. After the signal returns it selects a move again; it does not resume the old timeline.\n5. Assign red/blue frequency items if an external receiver is also needed.', '1. 添加累计伤害触发，无需标记。\n2. 阈值100、内部频道1、强度15、时长3秒；无线频道1启用并设为程序内部。\n3. 自定义动作抽选的触发选内部无线频道1，累计模块开启反转信号。\n4. 依次造成30、40、50点实际伤害，信号断开3秒，超出的20点不计；断开期间伤害不累计，结束后从0重新开始。自定义动作抽选失去触发时取消当前调度；信号恢复后重新抽选，不会续跑旧时间线。\n5. 需要外部接收时再配置红蓝频率物品。', 'Inactive triggers, disabled modules and master Off pause partial accumulation and pending output; an active pulse is ended and its cycle resets, with outputs zero. Re-enable to continue the unfinished partial count or pending output. Threshold edits reset that module counter. Reset clears accumulated damage, pending output and pulse. Death, Release and chunk unload clear temporary accumulation; presets/copies save settings only.\n\nUse a dedicated output channel/frequency: another high producer can mask the reverse interruption. Healing cannot cancel an interruption. Damage continues to affect HP during output; only its accumulation is suspended. This module pauses Move set by signal; it does not automatically pose the body, play a stagger animation or stop already launched attacks.', '触发未激活、模块禁用或总开关关闭时保留未完成的累计及待输出；正在输出则结束该轮并清零，输出为0。恢复后继续未完成累计或待输出。修改阈值会重置该模块计数，重置按钮清除累计、待输出及脉冲。死亡、解除及区块卸载会清除临时累计，预设/复制仅保留属性。\n\n输出应使用专用频道/频率，其他高信号来源可能遮盖反转断开。回血不会取消断开。输出期间仍正常受到伤害，只暂停伤害累计。本模块通过信号暂停自定义动作抽选，不会自动摆出倒地姿态或播放动画，也不会停止已经释放的攻击。'),
 'health_phase': ('Upper/lower HP percentages define a phase. Hold stays active in band; Enter emits a pulse on entry. Channel and power define output.', 'HP上下百分比定义阶段，Hold区间内持续，Enter进入时脉冲，频道/强度控制输出。', 'Set HP band and channel, connect a matching receiver, then damage across the boundary.', '设HP区间/频道，连匹配接收端，伤害跨过边界。', 'HP bounds are percentages, not absolute health. Check overlapping phases.', 'HP上下限为百分比，非绝对生命，检查阶段重叠。'),
 'sequence': ('Step outputs/times are edited in the sequence editor. Once/Repeat controls replay; Stop on low and reset source/channel govern restart.', '步骤输出/时间在序列编辑器，Once/Repeat控制重播，Stop on low及复位来源/频道控制重启。', 'Add two steps with different channels and timings, connect matching receivers, test Once then Repeat.', '加不同频道/时间两步，连匹配接收端，先测Once再Repeat。', 'Reset source must match as well as reset channel.', '复位来源及频道都需匹配。'),
 'sound': ('Approach/hurt/ambient/contact each use sound mixes. Event ranges, cooldowns, ambient timing and contact direction decide when they start.', '靠近/受伤/环境/接触分别用声音组合，事件范围、CD、环境节奏和接触方向决定开始。', 'Open an event sound, add layers, Preview, then configure event timing/range and test that event.', '打开事件声音，加层试听，设置事件节奏/范围，再测试事件。', 'Hearing range and event detection differ; empty mixes are silent. See Sound combinations.', '听觉范围与事件检测不同，空组合无声，详见声音组合。'),
 'trigger_sound': ('Trigger-driven sound mix, with playback mode, cooldown and repeat interval. Each layer owns Start/Pitch/Volume/Range.', '触发声音组合，另有模式/CD/重复间隔，各层独立Start/Pitch/Volume/Range。', 'Mark its origin, add a sound mix and choose move set or Hurt trigger. Test in a Move or independently.', '标记原点，加声音组合，选move set或Hurt，在招式或独立测试。', 'Action duration does not automatically truncate a sound. Use layer limit for cutoff.', '动作时长不自动截断声音，需截断用层Limit。'),
 'bgm': ('Start behavior, radius and fade govern background music. Layers retain delays/limits; natural playback follows BGM looping.', '启动/半径/淡入淡出控制BGM，层保留延时/截断，自然播放依BGM循环。', 'Add music layers, Preview, configure radius/fade, activate and approach/leave the creature.', '加音乐层试听，设范围/淡入淡出，激活后靠近/离开。', 'No Mark is needed. Nearby creatures compete for the music source; custom resources must exist locally.', '无需Mark，附近生命体会选择音乐来源，自定义资源需本地存在。'),
 'loot': ('Rolls and Chance/Weighted control item selection. Part loot is separate from whole-body death loot.', 'Rolls及Chance/Weighted控制选择，部位掉落与整机死亡掉落独立。', 'Mark a part, add item samples and configure selection. Destroy the part in a test copy; compare whole-body loot.', '标记部位，加物品样本及选择规则，在测试副本摧毁，与整机掉落比较。', 'Check sample chance/weight and which destruction event occurred.', '检查样本概率/权重及对应摧毁事件。'),
 'armor': ('Damage modifier ranges from -100% to +1000%, with scroll steps of 5. Positive increases damage; negative reduces damage; zero leaves it unchanged. +1000% means eleven times the original damage. The default 0% leaves damage unchanged. Set -100% explicitly for full immunity. Existing saved modifiers are preserved. Applies to the entire marked rigid body part.\n\nOverlapping active modifiers do not stack: the lowest signed value wins, preserving strongest-protection priority. Global adaptive defense measures and reduces damage after this modifier.', '伤害修正范围为−100%至+1000%，滚轮每格5。正数增伤，负数减伤，0不改变伤害。+1000%表示原伤害的11倍。默认0%不改变伤害，完全免伤需自行设置−100%。已有保存的修正值保持不变。作用于整个标记刚性部位。\n\n同一部位的多个生效修正不叠加，以最低数值为准，保留优先保护逻辑。全局自适应防御统计并削减修正后的伤害。', 'Mark a weak point and set +50%: a 20-damage hit becomes 30 before adaptive defense. Set -50% on a protected part to receive 10 instead; -100% prevents damage completely.', '标记弱点部位，设+50%：20点伤害在自适应防御前变为30点。防护部位设−50%则受到10点伤害，−100%完全免伤。', 'Lost/disconnected marks disable the modifier. Old positive reduction values automatically migrate to negative modifiers in saved worlds and presets. The module ID remains armor so existing Move set references remain valid.', '标记丢失或部位脱离后修正失效。旧世界及预设中的正数减伤自动转换为负数修正。模块内部ID仍为armor，已有自定义动作抽选引用继续有效。'),
 'sensor': ('Shape/radius/inner radius/front width/direction define detection; target and line of sight filter entities.', '形状/半径/内半径/前宽/方向定义检测，目标及视线过滤实体。', 'Mark sensor face, choose shape/targets/range, Preview and connect its signal outputs to receivers.', '标传感面，选形状/目标/范围，Preview并连接输出到接收端。', 'Out-of-shape and sight-blocked targets are ignored. Check routing independently.', '形状外/视线阻挡目标忽略，先独立检查信号路由。'),
 'laser': ('Charge precedes beam fire. Length/width define collision; beam hits/hit interval differ from firing Interval. Tracking and sweep change aim.\n\nBreak blocks defaults Off. Clear whole line removes breakable blocks intersecting the beam centerline during firing. Cut forward begins at the first obstruction and advances toward maximum beam length at Breaking speed (blocks/s, default 16). Destruction proceeds every firing tick, separately from entity hit intervals.\n\nOwn connected body is skipped. Unbreakable blocks, protected lifeform blocks and unloaded chunks stop the cut. No block item drops are created by the laser; containers can have their own removal effects. Breaking speed does not extend the burst: set enough Beam hits × Hit interval time to reach the endpoint. Signal loss or burst completion stops cutting. Charging and Preview never destroy blocks.', '蓄力先于发射，长度/宽度定义判定，命中数/命中间隔区别发射Interval，追踪及扫射控制瞄准。\n\n破坏方块默认关闭。瞬间清除整线在发射期间移除光束中心线相交的可破坏方块；逐步向前破坏从首个障碍开始，按破坏推进速度（格/秒，默认16）推进至最大光束长度。破坏在每个发射游戏刻推进，与实体伤害间隔分别计算。\n\n跳过自身连接主体。不可破坏方块、受保护生命体方块及未加载区块会挡住破坏；激光不生成方块物品掉落，容器可能执行自身移除行为。速度不延长发射时长，需要用命中次数×命中间隔留够推进时间；断信号或发射结束即停止。蓄力及预览不破坏方块。', 'Mark origin, choose aiming, short charge and safe length, Preview and trigger. Edit charge/fire sounds separately.', '标原点，选瞄准、短蓄力、安全长度，Preview并触发，分别编辑蓄力/发射声音。', 'Short activation may end before charging completes. Beam width is not particle size.\n\nAutomatic targeting still needs an initially visible target; use Fixed direction to start cutting a wall directly. A tracked target moving behind a breakable wall can be followed during firing. Extremely many cuts share a 1024-block removal budget per world tick; remaining obstructions stay until a later firing tick.', '激活太短可能蓄力未完，光束宽度非粒子大小。\n\n自动瞄准仍需初始可见目标；要直接从墙体开始切割，可用固定方向。已锁定目标在发射时跑到可破坏墙后，仍可追踪破坏。大量切割共用每世界每刻1024块移除上限，剩余障碍保留到后续发射游戏刻处理。'),
 'ground_strike': ('Mode/radius/range/rays or random count control placement. Start distance, wave delay and step control progression; warning precedes damage.', '模式/半径/距离/射线或随机数量控制放置，起始距离/波延迟/步进控制推进，预警先于伤害。', 'Mark origin, choose mode/color, Preview a short range then test; expand rays/area after confirming.', '标原点，选模式/颜色，Preview短范围再测，确认后扩展数量/范围。', 'Check placement/target modes; warning time is not repetition interval.', '检查放置/目标模式，预警时间非重复间隔。'),
 'quake': ('Line/ring/area and marked/target-foot origin shape the wave. Range/width/speed and wave gap control propagation. Grounded rules filter targets.', '线/环/区域及标记/目标脚下原点定义波，范围/宽度/速度/波间隔控制推进，接地规则筛选目标。', 'Mark origin, choose line/ring, modest range and warning; Preview then test a grounded target.', '标原点，选线/环、小范围及预警，Preview后测地面目标。', 'Airborne targets may be excluded. Wave travel is separate from attack interval.', '空中目标可能过滤，波推进与攻击Interval不同。'),
 'pull': ('Release position can use a marked point or the nearest eligible target as a fixed cast center; target mode needs no Mark. Radius chooses victims around that center. Stopping distance brakes/stops attraction near the center, not detection range. Defaults: beacon activate warning, beacon ambient pull. Strength/speed/stop distance control motion. Warning and pull duration separate anticipation and action.', '释放位置可用标记点或最近符合类型目标的固定位置，目标模式无需Mark；半径选中心周围被吸引者。停止距离是接近中心时刹停半径，不是检测范围。默认预警信标激活声，吸引信标环境声。强度/速度/停止距离控制移动，预警/持续区分准备和动作。', 'Mark center, choose targets/modest strength, Preview and test stop distance.', '标中心，选目标/适度强度，Preview并测停止距离。', 'Check range/line of sight. Entity types may react differently to motion.', '检查范围/视线，不同实体对位移响应可能不同。'),
 'pulse': ('Radius, damage and knockback define a radial pulse. Start distance offsets origin; Interval repeats it.', '半径/伤害/击退定义脉冲，起始距离偏移原点，Interval控制重复。', 'Mark origin, small radius/knockback, Preview then test one nearby target.', '标原点，小半径/击退，Preview后测一个附近目标。', 'Check target and interval. Knockback cannot guarantee motion through obstacles.', '检查目标/Interval，击退不保证穿过障碍。')}
for id in ('arrow', 'gun'):
    notes[id] = ('Speed/count/interval define volleys. Visual size differs from hitbox. Start distance moves large projectiles clear of the muzzle. Explosion and block breaking are separate.', '速度/数量/间隔控制齐射，视觉大小区别判定，起始距离避开大弹体炮口碰撞，爆炸与破坏方块独立。', 'Mark firing face, choose one projectile and safe reach, Preview direction and trigger. Increase count or add effects after basic firing works.', '标发射面，先一发和安全距离，Preview方向再触发，正常后加数量/效果。', 'Immediate collision usually needs clearance or Start distance; check direction before increasing damage.', '立即碰撞先检查净空/起始距离，提高伤害前确认方向。')
notes['slash']=('Start distance and horizontal/vertical offsets determine launch. Length spans the blade; Width is its depth. Range and blocks/s speed control flight. Count 1–16 and fan 0–180 degrees spread blades symmetrically; blade rotation tilts the slash plane. RGB defaults white, or choose particles with size/lifetime. Interval is release-to-release time: volleys can overlap while old blades continue flying. Release sound uses Sound mix.','Start distance及横向/垂直偏移定义发射。长度为横向跨度，宽度为飞行方向深度。射程及格/秒速度控制飞行。数量1–16、扇形0–180度对称展开，可旋转刃面。RGB默认白色，或选择自设大小/寿命粒子，Interval为两次释放间隔，允许多批同时飞行，旧斩击持续前进；释放音效使用Sound mix。','Mark a face; try length 4, width 0.5, speed 16 blocks/s, range 24. Preview direction. Set count 3 and fan 60 degrees for three rays; offsets change their common heading. Add effects and select Release sound, then activate or assign to Move set.','标一个面，先试长度4、宽度0.5、速度16格/秒、射程24。Preview方向，数量3、扇形60度产生三条，偏移改变共同朝向。追加Effect和释放音效，再激活或放进Move set。','Swept hitboxes prevent fast blades skipping targets. Each blade hits each eligible target once; multiple blades can each hit it. Launch frames freeze in world space and do not follow later body rotation. Center-path terrain stops a blade, and invisible targets behind walls are excluded; no terrain destruction. A required mark or trigger loss stops new launches; already released blades finish flying. Hurt Once releases only one volley; death/Release clear flights. At 256 blades per module, new launches wait for space without deleting old blades. Sound starts at the launch position; delayed mix layers are supported.','扫掠判定避免高速漏目标，每条斩击每符合类别目标一次，多条可分别命中。发射框架固定在世界，不跟随后续主体旋转。中心路径地形阻挡会停止斩击，隔墙不可见目标不受伤，不破坏地形。必需标记或触发丢失只停止新发射，已释放继续飞行；Hurt单次只发一批，死亡/Release清理飞行。每模块同时256条达到上限时等空位，不删除旧斩击。声音在发射位置开始，可设延后混音层。')
notes['sphere_blast']=('Release position defaults Marked point; At target samples the nearest eligible target in the search range and freezes its position at charge start, with no Mark required. Start distance clears the marked face; Distance from start places the sphere center further along that direction. Radius is spherical. Charging fixes the world point; targets can leave before the single explosion. New modules default charging to Small flame + Firework. Charging particles move all the way toward the center at Charging speed (default 2 blocks/s). Speed does not change Charge time. The explosion ends their lifetime, so a short charge can truncate slow travel. At explosion, selected charging and explosion particles expand from the center to the configured Blast radius at a fixed 12 blocks/s. The original damage radius is unchanged. Charging and explosion have independent particle selections and sound mixes, with hit Effects and optional block destruction (default Off).','释放位置默认标记点；目标身上在搜索范围内选最近符合类型目标，并在蓄力开始锁定位置，无需Mark。Start distance使起点离开标记面，距起始点距离沿同一方向定位球心。半径为球形。蓄力时固定世界位置，目标可在爆炸前离开。新模块默认Small flame＋Firework蓄力。蓄力粒子按蓄力速度（默认2格/秒）向中心移动；速度不改变蓄力时间。粒子在爆炸前结束，较短蓄力可能截断慢速运动。爆炸时蓄力和爆炸选择的粒子都从球心以固定12格/秒扩散到所设Blast radius边缘，原伤害半径保持。蓄力/爆炸分别选择粒子及声音组合，支持命中Effect，破坏方块默认Off。','Mark the firing face. Try Start distance 0, distance 8, radius 4, charge 2 s, interval 5 s. Preview the line and sphere. Select both particle/audio stages, then activate. In Move set give this action enough duration to finish charging.','标记发射面，先试起始距离0、距离8、半径4、蓄力2秒、间隔5秒。Preview检查直线和球形，设置两阶段粒子/声音后激活。Move set动作时长要足够完成蓄力。','Required mark loss, disabling or a falling trigger cancels pending charging. No path damage. Only loaded destinations execute; the attack never force-loads remote terrain. Each explosion damages each eligible target once without vanilla duplicate damage. Block destruction uses vanilla TNT resistance, not guaranteed removal of every voxel within damage radius.','必需标记丢失、禁用或触发结束会取消待爆蓄力。路径不造成伤害，仅在已加载目标执行，不强制加载远处地形。每次爆炸每符合类别目标只伤害一次，不叠加原版伤害。方块破坏使用原版TNT抗性，并非伤害半径内所有方块必毁。')
notes['auto_facing']=('Target type uses the shared player/mob/all/lifeform categories. Range limits selection; Turn speed is degrees per second, default 180. Horizontal tracking is default; vertical tracking tilts the whole machine. Creative players may be included. Line of sight defaults Off; On selects the nearest visible target, ignoring your own connected body.','目标类型共用玩家/生物/全部/其他生命体分类。检测距离限制选择，转速单位度/秒，默认180。默认水平追踪，垂直会倾斜整机，可包括创造玩家。Line of sight默认Off，On仅选最近无遮挡目标，自身连接主体不挡视线。','Add Auto facing, mark its front face, select Target type, range and speed. Preview the front line, then activate with Always trigger. Move an eligible target around it.','添加自动朝向，标记正面，选择Target type、距离、速度，Preview正面线，再用Always激活，让符合类型的目标绕行。','No visible eligible target means no rotation when Line of sight is On. Horizontal mode needs a nonvertical front face; enable vertical tracking for other faces. Collision check defaults On: terrain/bounding boxes block unsafe rotation; blocked vertical rotation still allows clear horizontal turning. Off skips that check and forces rotation even while intersecting terrain, at the configured turn speed. Direct movement wins; first active facing module controls the machine. Navigation still outputs signals for your mechanical design.','视线检查On时，没有可见的符合类型目标就不转动。水平模式需非竖直正面，其他面可开垂直追踪。碰撞判定默认On，地形/碰撞箱阻挡不安全转动，垂直受阻时水平仍在安全范围继续。Off跳过此检查，按设定转速强制转动，即使与地形重叠，直线移动优先，仅第一个激活朝向模块控制整机。Navigation仍是给玩家自制机械输出信号。')
for id, values in notes.items():
    chapter(id, None, [('',''), values[:2], values[2:4], values[4:6]], True)
    entries[-1]['sections']['usage'] = ['dashboard.sablelife.description_' + id]

for id, en, zh in [('arena','Manage the creature leaving a fixed arena, with nearby-player warnings and optional punishment or return.','管理生命体离开固定场地后的附近玩家警告、可选惩罚或归位。'),('navigation','Output navigation signals for a player-designed movement and aiming mechanism.','为玩家自制移动及瞄准机构输出导航信号。'),('pulse','Apply radial damage and knockback pulses around a marked origin.','以标记原点产生范围伤害及击退脉冲。')]:
    next(e for e in entries if e['id']==id)['sections']['usage']=[text(id+'.usage',en,zh)]
# Movement direction and facing are intentionally separate; document the practical sequence.
linear = list(notes['linear_movement'])
linear[2] += '\n\nFacing example: if the marked face points North and the selected player is South behind the machine, target movement displaces it South while retaining its North-facing orientation. To face the player first, configure Auto facing with a matching target type/range, allow enough time to align, then start Linear movement. In Move set, place turning before displacement.'
linear[3] += '\n\n朝向示例：标记面朝北，选中的玩家在机器后方南侧时，目标移动会向南位移，但机器仍保持朝北。需要先面向玩家时，先用自动朝向，设置匹配的目标类型/范围并留足转向时间；确认正面已对准，再开始直线移动。自定义动作抽选中可把转向放在位移之前。'
notes['linear_movement'] = tuple(linear)
facing = list(notes['auto_facing'])
facing[4] += '\n\nLinear movement takes control from charging until movement finishes, including the teleport tick, so Auto facing pauses during that interval. Target-directed displacement does not itself rotate the machine. Turn before moving if the front must face the target; turning may remain incomplete if blocked or given too little time.'
facing[5] += '\n\n直线移动从蓄力开始到位移结束（包含传送当刻）优先控制机器，期间自动朝向暂停。朝目标位移本身不会旋转机器；需要正面朝向目标时应先转向再移动。转向被挡或时间不足时，可能尚未完成对准。'
notes['auto_facing'] = tuple(facing)

chapter('item_display', None, [
 ('Display a selected item at a marked body point. This is a cosmetic function and creates no entities, collision, damage or collectible items.', '在标记点显示所选物品，是纯外观功能，不生成实体、碰撞、伤害或可拾取掉落物。'),
 ('Choose the displayed item in the sample slot. It is copied with its item data, never consumed. The same handheld-model renderer as homing projectiles preserves model-based weapons.\n\nSize controls the longest model dimension, 0.05–32 blocks. XYZ offsets use the marked body local axes, −64 to 64 blocks. X/Y/Z rotations are local degrees, −180 to 180, applied in XYZ order. The model follows its marked limb.\n\nAlways display defaults Off: enabled life activation and trigger are required. On ignores both activation and trigger, including while dormant, but still requires an enabled module and a connected valid mark. Redstone Cores can also use this cosmetic module. Preview outlines the maximum model size, not a damage hitbox.', '在样本格选择显示物品，复制物品及其数据，不消耗；使用与追踪弹相同的手持模型渲染，保留模型武器外观。\n\n大小控制模型最长边，范围0.05–32格。XYZ位置偏移按标记主体局部坐标轴计算，范围−64至64格；X/Y/Z角度范围−180至180度，按XYZ顺序旋转。模型跟随标记肢体。\n\n始终显示默认关闭，需要生命激活且满足触发。开启后忽略激活及触发，休眠也显示，但仍需模块启用及有效连接标记。红石核心也可使用这个外观模块。预览框表示模型最大尺寸，不是伤害判定。'),
 ('1. Add Item display and choose a sword in Displayed item.\n2. Mark the intended hand face.\n3. Adjust size, XYZ offset and the three rotations; Preview its extent.\n4. Turn Always display On to inspect while editing, or leave it Off and activate its trigger.\n5. Save preset if you want to reuse the appearance; mark again on the new body.', '1. 添加物品显示，在显示物品中选择一把剑。\n2. 标记手部目标表面。\n3. 调整大小、XYZ位置及三轴旋转，预览外框。\n4. 编辑时可开启始终显示；关闭时需要激活及满足触发。\n5. 需要复用可保存预设，在新主体上重新标记。'),
 ('No item, disabled module or lost/disconnected mark means no display, even with Always display On. Ordinary item textures remain ordinary models; this does not invent a new 3D model. Custom assets must exist on viewing clients. Unloaded bodies are not force-loaded for this feature.', '未选物品、禁用模块、标记损毁或脱离时不显示，即使始终显示开启。普通物品仍使用原有模型，不会自动生成新的立体模型；自定义资源需存在于观看客户端。该功能不会强制加载未加载主体。')], module=True)
for module_id in ('linear_movement','auto_facing'):
    for tab, pair in zip(('settings','example','troubleshooting'), zip(notes[module_id][::2],notes[module_id][1::2])):
        text(module_id+'.'+tab,*pair)
text('module_management.color_picker', 'RGB opens one shared in-game color picker for every existing module color: Mortar warning, Ground strike, Laser, Quake, both Attraction colors and Slash. Drag the square to select saturation/brightness and the rainbow strip for hue. The preview shows original on the left and new on the right.\n\nPrecise RGB expands three synchronized 0–255 fields; numeric edits also move the picker. Confirm sends one atomic update. Use presets restores the preset selector and remembers your custom color. Cancel/Escape changes nothing. Saved worlds and presets retain the same RGB values; the dashboard no longer needs three separate rows.', '所有现有模块颜色统一使用游戏内色盘：迫击炮预警、地面攻击、激光、地震、吸引的两种颜色及斩击。点击RGB后，拖动方形选择饱和度/明暗，彩虹条选择色相；预览左侧原色、右侧新色。\n\n精确RGB展开三个自动同步的0至255输入框，修改数字也会移动色盘。确定时一次保存，使用预设恢复预设按钮并保留自定义颜色，取消/Escape不改变设置。存档和预设沿用原RGB值，属性面板不再占用三排数值框。')
next(e for e in entries if e['id']=='module_management')['sections']['settings'].append('manual.sablelife.module_management.color_picker')
text('module_management.manual_controls','The manual header provides Language, UI density and Back. Language switches the game resources without restarting; returning preserves the chapter, tab and search. UI density uses the same saved preference as the dashboard and adjusts text wrapping and row spacing. Right-click density to cycle backward.','手册右上角提供语言、界面密度及返回。语言切换无需重启，返回保留章节、页签与搜索；界面密度与面板共用保存的偏好，并调整正文换行及列表行距，右键密度可反向切换。')
next(e for e in entries if e['id']=='module_management')['sections']['settings'].append('manual.sablelife.module_management.manual_controls')
source=(root/'src/main/java/dev/sablelife/module/VirtualModule.java').read_text(encoding='utf-8')
order=re.findall(r'"([a-z_]+)"', source.split('AVAILABLE_TYPES = List.of(')[1].split(');')[0])
entries.sort(key=lambda e: order.index(e['module'])+100 if 'module' in e else 0)
# Withdraw the provisional example; keep the generic timeline renderer for future examples.
entries=[e for e in entries if e['id']!='combo_flame']
for locale in locales:
    for key in list(locale):
        if key.startswith('manual.sablelife.combo_flame.') or key=='manual.sablelife.chapter.combo_flame': del locale[key]

for locale in locales:
    for key in list(locale):
        if key.startswith('manual.sablelife.core_operations.') or key=='manual.sablelife.chapter.core_operations': del locale[key]

text('module_management.presets', 'Save preset beside Delete opens a name box with Confirm and Cancel. Presets persist in the client config across worlds.\n\nThey keep applied module settings, sound layers, particles and effects; marks, arena positions and references to other modules must be assigned again.\n\nDuplicate names receive a numeric suffix. Custom audio files must still exist on listening clients.', '属性面板底部删除模块左侧的保存预设会打开收藏名称输入框，右边可确定或取消。预设保存在客户端配置中，可跨世界使用。\n\n预设保留已应用的模块属性、声音层、粒子及状态效果；标记、场地中心和其他模块引用需要重新设置。\n\n重复名称自动加数字后缀，自定义音频仍需在听觉客户端存在。')
next(e for e in entries if e['id']=='module_management')['sections']['settings'].append('manual.sablelife.module_management.presets')

text('core.death_envelope', 'Immediate death effects originate at the center of the connected body, including attached parts. Effect radius 0 automatically fits its enclosing sphere (up to 256 blocks); a positive value sets a fixed radius. Spread controls jitter. Burst/cloud particles start around that sphere; ring, star and spiral keep their selected shapes. Flash remains a single central flash. Sound radius is independent.\n\nAfter the death delay, removal effects still appear at constituent blocks while cleanup runs in batches. Rewards keep their existing location.', '死亡瞬间特效以整个连接结构的中心为原点，包含连接的部位。效果半径为 0 时按结构外接球自动计算，最多 256 格；正数则使用指定半径。扩散值控制粒子的散布。爆发和云状粒子从球面生成，圆环、星形和螺旋保留所选形状，闪光仍在中心播放一次。声音传播半径独立设置。\n\n死亡延迟结束后，残影特效仍在组成方块处生成，结构分批清除。战利品位置沿用原有规则。')
for entry in entries:
    if entry['id']=='core':entry['sections']['settings'].append('manual.sablelife.core.death_envelope')
text('core.protected_tools', 'When Allow block breaking is Off, tools aimed at an activated body attack it instead of mining. Holding the button does not keep producing cracks or block-hit particles. Ordinary terrain and tool mining with Allow block breaking On keep their previous behavior.\n\nWith Epic Fight 21.17.3.1, supported native main-hand hits also charge the matching weapon innate skill by health damage actually dealt. The native skill cap, activation state and synchronization apply; the same phase cannot charge twice. Immunity yields no charge. This does not imply support for entity-only skill events or other combat mods.', '允许方块破坏关闭时，工具对准已激活的生命体会进行攻击，不进入挖掘；长按也不会持续产生裂纹或挖掘粒子。普通地形，以及允许破坏开启时的工具挖掘，保持原有行为。\n\n安装 Epic Fight 21.17.3.1 时，已适配的主手原生攻击会按实际扣除的生命值为对应武器的特殊技能充能，沿用原模组的上限、激活状态和同步方式。同一攻击阶段不会重复充能，免伤时不充能。这不代表已适配仅面向实体的技能事件或其他战斗模组。')
for entry in entries:
    if entry['id']=='core':entry['sections']['usage'].append('manual.sablelife.core.protected_tools')


text('core.boss_colors', 'The Boss bar switch has a color selector beside it. Left-click cycles forward and right-click cycles backward through pink, blue, red, green, yellow, purple and white. Red remains the default for old worlds. Color persists in world saves and copied core configurations, and can be changed while alive without resetting health.', 'Boss 血条开关旁可选择颜色。左键切换下一种，右键切换上一种，共有粉、蓝、红、绿、黄、紫、白七种原版颜色。旧存档默认仍为红色。颜色随存档与核心配置复制保存，生命体存活时也可切换，不会重置生命值。')
next(e for e in entries if e['id']=='core')['sections']['settings'].append('manual.sablelife.core.boss_colors')
text('death_unloading.cleanup_resume', 'Cleanup progress is saved with the world. If you leave during a large creature’s batched removal, loading the world again resumes the remaining cleanup instead of restarting the whole death or granting its reward again. Unloaded areas wait until loaded; this is different from the death-delay countdown. Removal effects remain at the blocks being cleaned.', '大型生命体分批清除时，清除进度会随世界保存。清除过程中退出游戏，再进入后会继续处理剩余结构，不会重新开始整次死亡，也不会因此重复发放战利品。未加载区域需要等到加载后才能清理，这与死亡延迟倒计时是两个阶段。残影特效仍在正在清除的方块上生成。')
next(e for e in entries if e['id']=='death_unloading')['sections']['usage'].append('manual.sablelife.death_unloading.cleanup_resume')
text('melee.epic_guard', 'With supported Epic Fight 21.17.3.1, Melee module attacks can be guarded or parried using its normal front-facing, held-weapon and skill rules. Native stamina, penalty, guard-break animation and parry timing remain in effect. The attack origin is the marked body’s world position; attacks from behind are not blocked.\n\nA blocked contact waits for the configured Interval before trying again, without applying damage, hit effects or module knockback. Successful-hit limits are not consumed by blocks. No proxy attacker is spawned. This bridge does not change Arrow/Gun blocking or make all module attacks blockable.', '安装已适配的 Epic Fight 21.17.3.1 后，近战模块可按原模组的正面朝向、持握武器及技能规则进行格挡或招架，沿用体力消耗、惩罚、破防动作及招架时机。攻击来源为标记所在主体的世界位置，后方攻击不能格挡。\n\n挡住一次接触后，会等待模块设定的攻击间隔再尝试，不施加伤害、命中状态效果或模块击退，也不占用成功命中次数上限。不会生成代理攻击者。此次接入不改变箭矢、枪弹的格挡，也不代表所有模块攻击都可以格挡。')
next(e for e in entries if e['id']=='melee')['sections']['settings'].append('manual.sablelife.melee.epic_guard')

text('arena.range_buffs', 'Range buffs defaults Off. Enable it and open Buff groups to add, reorder or delete up to 16 groups. Each group chooses up to 16 persistent effects and levels 1–5. Instant healing/damage effects are excluded. Duration is fixed at 2 seconds and refreshes once per second.\n\nAll groups share the existing Player range around the core, measured horizontally, and affect only alive survival players in the same dimension. This works while the boss is inside its Arena; the existing outside-Arena warning/return rules are unchanged. The Arena must be enabled, marked and triggered.\n\nFollow module adds no extra signal requirement. Internal channel reads a core wireless output; External channel reads its receiver input. Channel 0 is unbound. Configure external red/blue frequencies in the core Wireless editor. Several groups can be active together; the strongest level is chosen when the same effect occurs in multiple groups.\n\nFor a half-health change, set Health phase signals for the desired health ranges, output to internal channels 1 and 2, and bind the corresponding groups. At a boundary both phases can be active if their configured ranges overlap. Signal off, leaving the range, disabling or death stops refreshes; short-lived effects expire naturally, so old/new stages may overlap briefly. No blanket removal is used on player potion effects. Saved worlds/core copies retain groups and channels; presets retain effects and control modes but require channel rebinding.', '范围 Buff 默认关闭。开启后进入效果组编辑页，可添加、排序或删除最多 16 组效果。每组最多选择 16 种持续效果，等级 1–5；不提供瞬间治疗、瞬间伤害等即时效果。持续时间固定为 2 秒，每秒刷新一次。\n\n所有效果组共用核心周围现有的 Player range，按水平距离计算，只作用于同一维度内存活的生存玩家。Boss 位于场地内时也能给予效果；原有越界警告和返回规则不变。场地模块必须已启用、已标记且触发成立。\n\n跟随模块不要求额外信号；内部频道读取核心无线输出，外部频道读取接收输入。0 表示未绑定。外部红蓝频率在核心的无线频道编辑页设置。多个效果组可同时生效，同类效果取最高等级。\n\n例如半血切换：用生命阶段模块设置对应的生命区间，分别输出到内部频道 1、2，再将两个效果组绑定到这些频道。若阶段区间重叠，边界处可能同时生效。断开信号、离开范围、停用或死亡后停止刷新，效果自然结束，因此新旧阶段可能短暂重叠。不会统一清除玩家自己的药水效果。存档及核心复制保留效果组和频道；预设保留效果与控制方式，但频道需要重新绑定。')
next(e for e in entries if e['id']=='arena')['sections']['settings'].append('manual.sablelife.arena.range_buffs')

text('core.iron_spells', 'Iron’s Spells compatibility targets the inspected Minecraft 1.21.1 / 3.16.3 release. Supported moving damage projectiles are Magic missile, Magic arrow, Small fireball, Firebolt, Icicle, Lightning lance and Blood slash, plus Fireball and Fire arrow explosions. Hitting a living body consumes the projectile, including piercing types, after one body damage calculation. Ordinary living targets keep native behavior. Explosive projectiles retain native blast damage and effects without a second TNT-formula hit.\n\nFire breath, Cone of cold and Poison breath use their native attack-part boxes and damage activation windows. Multiple parts touching one creature count once per window. Terrain blocks these attacks. Ray of siphoning uses the native ray and cast pulses; it heals the caster by actual body health removed. Blood slash retains its native 15% lifesteal. Part modifiers and adaptive defense still apply; fully immune bodies do not provide healing.\n\nNo proxy entities are spawned. Unknown projectile families, lock-on, chains, lightning balls and other ground waves still need explicit adapters. Burning, freezing, poison status effects and native LivingEntity-only damage/skill events are not simulated on bodies. Addons retaining a supported path can inherit it; independent paths need verification. Unverified Iron versions receive no hooks.', '铁魔法适配针对已核对的 Minecraft 1.21.1／铁魔法 3.16.3。支持的移动伤害弹体包括魔法飞弹、魔法箭、小火球、火焰箭（Firebolt）、冰锥、雷鸣长枪和猩红斩击，以及火球和 Fire arrow 的爆炸。命中生命体后结算一次并清除弹体，穿透类也会停止；打向普通生物时保留原生行为。爆炸弹体保留原生范围伤害和特效，不叠加 TNT 公式伤害。\n\n火焰吐息、刺骨寒风和毒雾喷射按原生攻击部件碰撞箱与伤害开启窗口判定。多个部件同时接触同一生命体，每个窗口只结算一次，地形仍会阻挡。血吸光束按原生射线及施法脉冲结算，以生命体实际损失的生命值为施法者回血；猩红斩击保留原生 15% 吸血。部位修正和自适应减伤继续生效，完全免疫的身体不提供回血。\n\n不生成实体代理。未知飞行物家族、锁定、连锁、雷球、持续云和地面波仍需明确适配；燃烧、冻结、中毒等状态效果，以及仅面向 LivingEntity 的伤害或技能事件，不会在身体上模拟。保留已支持路径的附属可共用接口，独立路径仍需核对。未经核对的铁魔法版本不会注入接口。')
next(e for e in entries if e['id']=='core')['sections']['usage'].append('manual.sablelife.core.iron_spells')

text('core.iron_areas', 'Additional inspected paths: Shadow slash damages real body voxels in its impact area. Wither skull applies one full direct body hit and nearby damage; Starfall comets apply their native flat area damage; Arrow volley’s individual small arrows each damage once and stop at a body. Sunbeam retains its native 15-tick warmup and single area burst.\n\nEarthquake, Fire fields and Poison clouds follow the native checkHits cadence, startup delay and duration. Circular areas retain the radius as well as their vertical box limits. One pulse can hit several creatures, but multiple body blocks count once per creature; hit-based radius and duration changes occur once for the entire pulse. An immune contact still counts for these native post-hit rules.\n\nHealing areas and freeze-only fields are not converted into body damage, even when their internal amount is positive. Body damage does not simulate native poison, fire or freezing status ticks. Other area families still need verification.', '新增已核对路径：暗影斩击可按冲击范围伤害真实身体；凋零之首保留一次完整直接命中与附近伤害，星海落瀑的彗星保留原生范围伤害，万箭齐发的每支小箭独立扣血并在身体处停止。烈阳射线保留原生 15 tick 预热和一次区域爆发。\n\n地震、火焰区域和毒云按原生伤害周期、启动延迟和持续时间判定。圆形区域同时保留半径与高度限制；一次脉冲可命中多个生命体，但同一生命体的多个方块只结算一次。命中后的半径及持续时间变化，每次脉冲只执行一次；免疫接触仍计入这些原生后续规则。\n\n治疗区域和仅施加冻结的区域不会被转成伤害，即使内部数值为正也一样。生命体伤害不模拟原生中毒、燃烧或冻结状态的持续扣血。其他范围技能家族仍需核对。')
next(e for e in entries if e['id']=='core')['sections']['usage'].append('manual.sablelife.core.iron_areas')

text('arena.respawn', 'Automatic respawn defaults Off and requires the inspected Sable Photomancy 1.0.1 optional API. Without it, other Sable Life features remain available and respawn controls are disabled. A creative operator records the current connected structure after marking the Arena center, then enables Automatic respawn and sets its cooldown (5–3,600 seconds, default 60; scroll ±1 second). One record per creature; record again replaces it.\n\nThe record preserves structure poses relative to the Arena center, core settings, modules, internal references and inventory. Death begins the cooldown. The spawn region must be loaded; its countdown and building pause without forcing chunks. Old body and detached-part cleanup must finish first. The structure restores incrementally, then a fresh creature activates at full health with new identities, valid marks and reset runtime. Every part actually rebuilt from the template is registered to the new creature, even if its connection actor is not ready yet, so later death cleanup includes all recorded parts. Multiple generations reuse the template.\n\nCountdown and a progress bar appear at the Arena center. Partial build progress is stored in world data, independent of the deleted core. Clear record stops future respawns without deleting the live creature. An operator standing within 64 blocks can use /sablelife_respawn cancel after the core is gone; it cancels the record and removes only its known partial build bodies. A failed build stops rather than repeatedly creating structures. The failure display includes the cancellation command. That command also removes orphaned copies of the same respawn display. Partial reconstructed bodies pause block-entity ticks until their complete NBT and joint commit; unrelated bodies run normally. Save/reload reinstates this guard before world ticking.\n\nRecords are server-side and excluded from GUI snapshots, presets and ordinary blueprint copies. Limits: 32 records per world/server, 32 connected parts, 131,072 blocks and 16,384 block entities by default (server arenaCaptureBlocks / arenaCaptureBlockEntities), 256 captured entities, 4,194,304 bounding-box scan cells by default (including air, adjustable with the server arenaCaptureScanVoxels budget), 32 MiB per template and 128 MiB of templates per world by default (server arenaTemplateBytes / arenaWorldTemplateBytes). A rejected capture reports the exact limit, measured value and maximum. Unallocated air chunks inside a plot bounding box are valid holes, not unloaded parts. Capture checks only allocated plot chunks and uses Sable’s native empty-chunk reads for holes without creating chunks. Independent structures outside Sable’s connected chain are not included merely because a rope is nearby. Blueprint hooks preserve supported joints and extra data; unverified third-party structures still require playtesting. Recorded inventory is restored each generation; loot duplication is intentional for an administrator-authored encounter. Native blueprint finalization has work beyond block placement; no constant-latency guarantee is made for every addon.', '自动重生默认关闭，需要已核对的可选 API：Sable Photomancy 1.0.1。未安装时，其他功能正常，重生选项禁用。由创造模式管理员先标记场地中心，再记录当前相连结构、开启自动重生并设置间隔。间隔为 5–3,600 秒，默认 60 秒，滚轮每次 ±1 秒。每个生命体只绑定一份记录，重新记录会替换模板。\n\n模板保留相对场地中心的位置与朝向、核心设置、模块、内部引用和库存。死亡时开始倒数；重生区域未加载时暂停倒数和建造，不强制加载区块。旧身体及脱离部位清理完成后，才分批恢复结构。新生命体使用新的身份、有效标记和清空的运行状态，满血后直接激活；下一次死亡继续复用模板。蓝图实际重建的全部部件都会登记到新生命体，即使连接部件尚未就绪，后续死亡清理也包含这些已记录身体。\n\n场地中心显示倒数和进度条。记录及部分建造进度存于世界数据，不依赖已删除的核心。清除记录只停止后续重生，不删除当前存活的生命体。核心消失后，管理员可站在场地中心 64 格内执行 /sablelife_respawn cancel，取消记录并清理这份任务已创建的部分结构。建造失败时会停止，不反复生成；失败提示会显示取消命令，该命令也可清掉孤立的同任务提示副本。重建中尚未提交完整 NBT 和关节的身体会暂停方块实体 tick，其他结构正常运行；存档恢复后会在世界 tick 前恢复这项防护。\n\n记录只存服务端，不塞入界面快照，也不跟随预设或普通蓝图复制。上限为每个世界/服务器 32 份记录、32 个相连部件、默认 131,072 个方块、16,384 个方块实体（服务器 arenaCaptureBlocks / arenaCaptureBlockEntities 可调整）、256 个被记录实体、默认 4,194,304 个包围盒扫描格（含空气，可通过服务器 arenaCaptureScanVoxels 预算调整），默认每份模板 32 MiB、全世界模板合计 128 MiB（服务器 arenaTemplateBytes / arenaWorldTemplateBytes 可调整）。超限时会显示具体项目、实际值和上限。plot 包围盒里没有分配区块的空气空洞，不属于未加载部件；记录只检查实际分配的结构区块，空洞由 Sable 原生空区块读取处理，不创建区块。未被 Sable 相连结构链纳入的独立结构，不会仅因附近有绳索就额外记录。蓝图接口保留其支持的关节和附加数据，未经核对的第三方结构仍需实测。每代都会恢复记录的库存，这是管理员编写重复战斗场景的功能。原生蓝图最终提交还有方块放置以外的工作，不能保证所有附属都具有固定耗时。')
next(e for e in entries if e['id']=='arena')['sections']['settings'].append('manual.sablelife.arena.respawn')
text('core.iron_physical_followup', 'Additional physical damage paths: Creeper mortar keeps its quadratic radius falloff; Divine smite uses its native forward box and weapon/spell damage; summoned fangs hit once at their native bite window on real ground; Ice block keeps its harmless floating phase, half-damage falling contact and cubic-falloff ground burst. A falling ice block consumed by body contact does not also burst on that same victim.\n\nThese adapters add no synthetic body entity, UUID target or entity lock-on. Native spells may retain their normal mob targeting, but the body damage paths use physical overlap, native ray positions or actual impact areas. Strict entity-targeted spells are excluded by scope. Pure freezing/poison/fire status effects still are not simulated on body voxels.', '新增物理伤害路径：苦力怕迫击炮保留平方距离的范围衰减；神圣打击使用原生前方攻击盒及武器、法术伤害；唤魔尖牙在真实地面上按原生啃咬时刻结算一次；霜降保留悬浮期间不伤害、下坠接触半伤害，以及落地时按三次方距离衰减的爆发。冰块接触身体后消失时，不会再给同一目标叠加落地爆发。\n\n这些接口不生成身体实体，也不建立身体 UUID 目标或实体锁定。法术原来对普通生物的目标获取继续保留，机械身体的伤害仅来自实际接触、原生射线位置或攻击区域。必须指定生物目标的法术不在适配范围内。仅冻结、中毒、燃烧等状态效果仍不会在身体方块上模拟。')
next(e for e in entries if e['id']=='core')['sections']['usage'].append('manual.sablelife.core.iron_physical_followup')

# Editorial boundaries are explicit, rather than splitting every sentence or fixed character counts.
# Keep these outside the content definitions so regeneration preserves the reviewed layout.
paragraphs = json.loads((root / 'scripts/manual-paragraphs.json').read_text(encoding='utf-8'))
for lang, locale in zip(('en_us', 'zh_cn'), locales):
    for suffix, boundaries in paragraphs.items():
        key = 'manual.sablelife.' + suffix
        value = locale[key]
        for start in boundaries[lang]:
            assert value.count(start) == 1, (lang, key, start)
            before, after = value.split(start, 1)
            assert before.strip(), (lang, key, 'empty opening paragraph')
            before = before.rstrip()
            if lang == 'zh_cn' and before.endswith(('，', '；')):
                before = before[:-1] + '。'
            value = before + '\n\n' + start + after
        locale[key] = value
    # Numbered procedures retain their sequence; each step gets breathing room.
    for entry in entries:
        for keys in entry['sections'].values():
            for key in keys:
                locale[key] = re.sub(r'(?<!\n)\n(?=\d+\. )', '\n\n', locale[key])

(base / 'manual').mkdir(exist_ok=True)
(base / 'manual/catalog.json').write_text(json.dumps({'revision':64,'entries':entries}, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
locales[1] = localize(locales[1])
for lang, locale in zip(('en_us','zh_cn'), locales):
    (base / f'lang/{lang}.json').write_text(json.dumps(locale, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
